   108→+// ResolveSessionFile returns the path to a Gemini session file.
   109→+// Gemini names files as session-<date>-<shortid>.json where shortid is the first 8 chars
   110→+// of the session UUID. This searches for an existing file matching the pattern, falling
   111→+// back to <dir>/<id>.json if no match is found.
   112→+func (g *GeminiCLIAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
   113→+	// Try to find existing file matching Gemini's naming convention:
   114→+	// session-*-<first8chars>.json
   115→+	shortID := agentSessionID
   116→+	if len(shortID) > 8 {
   117→+		shortID = shortID[:8]
   118→+	}
   119→+
   120→+	pattern := filepath.Join(sessionDir, "session-*-"+shortID+".json")
   121→+	matches, err := filepath.Glob(pattern)
   122→+	if err == nil && len(matches) > 0 {
   123→+		// Return the most recent match (last alphabetically, since date is in the name)
   124→+		return matches[len(matches)-1]
   125→+	}
   126→+
   127→+	// Fallback: construct a default path
   128→+	return filepath.Join(sessionDir, agentSessionID+".json")
   129→+}
