   208→+// AllProtectedDirs returns the union of ProtectedDirs from all registered agents.
   209→+func AllProtectedDirs() []string {
   210→+	// Copy factories under the lock, then release before calling external code.
   211→+	registryMu.RLock()
   212→+	factories := make([]Factory, 0, len(registry))
   213→+	for _, f := range registry {
   214→+		factories = append(factories, f)
   215→+	}
   216→+	registryMu.RUnlock()
   217→+
   218→+	seen := make(map[string]struct{})
   219→+	var dirs []string
   220→+	for _, factory := range factories {
   221→+		for _, d := range factory().ProtectedDirs() {
   222→+			if _, ok := seen[d]; !ok {
   223→+				seen[d] = struct{}{}
   224→+				dirs = append(dirs, d)
   225→+			}
   226→+		}
   227→+	}
   228→+	slices.Sort(dirs)
